INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1022007-mkt250', 'stk-user2838', 'MKT 250', 'info', '{"desc": "كورس عام يقدم المبادئ الأساسية لعالم الماركتنج …\n\nالكورس سهل و ممتع لإحتوائه على أمثلة واقعية في حياتنا …\n\nالكورس يغطي عدة مفاهيم أساسية مثل الـ ( marketing mix , marketing environment , Advertising )\n\nبالإضافة لبعض المفاهيم الأخرى و لكن بدون تعمق …\n\nسلبية الكورس الوحيدة هي طول الكتاب المقرر … حوالي 24 تشابتر …\n\nالكثير من الدكاتره يضطرون لسلق الكثير من الماتيريال حتى يغطوا جميع المنهج المقرر …\n\nأخيرا أنصح بالدكتور صالح الشبل خصوصا لطلاب الماركتينج …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mkt-250-principles-of-marketing/121007/2", "user": "user2838", "ts": 1334368758000, "tid": 121007, "pn": 2}}', 1334368758000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1453428-mkt250', 'stk-user10207', 'MKT 250', 'info', '{"desc": "اسم الكورس MKT 250\n\nالكورس يتكلم عن مبادئ التسويق. الي هو بشكل عام عبارة عن عملية انتاج وتوزيع وترويج وتسعير المنتجات، الخدمات، والأفكار . التكامل مابين الأربعة أشياء هذي Marketing Mix والي هي راح يتكلم عنها الكتاب من اوله الى آخره.\n\nالكورس طويل الشباتر الي معك بالكورس 19 شبتر\nChapter 1\nStrategic marketing management\nChapter 2\nDeveloping and implementing marketing strategies\nChapter 3\nThe global marketing environment\nChapter 4\nInformation for marketing decisions\nChapter 5\nSelecting target market\nChapter 6\nConsumer behavior\nChapter 7\nBusiness buying behavior\nChapter 9\nDigital marketing and social media\nChapter 10\nProduct decisions\nChapter 11\nStrategic product management\nChapter 12\nServices marketing\nChapter 13\nStrategic management of branding and packaging\nChapter 14\nSupply-chain management and marketing channels\nChapter 15\nRetailing, wholesaling, and direct marketing\nChapter 16\nIntegrated marketing communications\nChapter 17\nAdvertising and public relations\nChapter 18\nPersonal selling and sales promotion\nChapter 19\nStrategic pricing management\nChapter 20\nPricing decisions\nChapter 21 (للقراءة فقط)\nGlobal issues, social responsibility, and marketing ethics.\n\nعدد صفحات الشباتر 730 جدا كبير الكتاب ومتعب بالقراءة\nالسلايدات تكفي عشان تفهم وتحل بالاختبار سواء كانت كتابة ولا اختيارات\nالكتاب اسمه Marketing للمؤلفين Hult, Pride, and Ferrel الطبعة 17\nالكتاب امريكي وكله امثلة من امريكا ماتحتاجها. اذا انت مهتم بالتسويق اقرا من الكتاب\nطبعا الكورس هذا الاشياء الـ basics يعني تقريبا كل شبتر له كورس بالجامعة بتخصص التسويق او بالجامعات الثانية.\nالميجر الاول 6 شباتر والثاني نفس الشيء.\nفيه بروجكت نهاية الترم وعليه برزنتيشن وريبورت . تسوي marketing plan او بعض السمسترات تسوي فكرة تسويقية جديدة.\nانصح بالقحطاني والشريدة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mkt-250-principles-of-marketing/121007/4", "user": "user10207", "ts": 1468139955000, "tid": 121007, "pn": 4}}', 1468139955000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1485729-mkt250', 'stk-maxmx05', 'MKT 250', 'info', '{"desc": "المادة هي MKT 250\n\nالمادة طووووووويلة جدا جدا. المادة تحتاج حفظ بشكل كبير جدا. يعني ما ينقع تذاكر قبل الميد ترم ب 4 ايام كلش ما يمدي لان الميد 10 شباتر محشوة حشو. كذلك الفاينل.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mkt-250-principles-of-marketing/121007/6", "user": "Maxmx05", "ts": 1515406634000, "tid": 121007, "pn": 6}}', 1515406634000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1289688-mkt250', 'stk-fsstsst', 'MKT 250', 'info', '{"desc": "انا طالب هندسه ودي انزل هالكورس mkt 250\nالدكتور هو NASSER AL-QAHTANI\nكيف الكورس هل هو كورس قريد\nوكيف طريقه المياجر والدرجات\nوبالنسبه للدكتور\nالتحضير :\nطريقة الشرح :\nالكويزات :\nالكلاس ورك :\nمشكورين مقدما\nالرجاء من المشرف عدم نقل الموضوع لمده 24 ساعه\nلاني محتاج الرد ضروري قبل التسجيل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mkt-250/152585/1", "user": "fsstsst", "ts": 1384793649000, "tid": 152585, "pn": 1}}', 1384793649000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hard-worker-mkt250', 'stk-hard-worker', 'MKT 250', 'doc', '{"docs": [{"id": "stk-dr-f98464", "n": "Dr. Obaid Al-Shuridah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MKT250 أخذتها في 152\nالدكتور عبيد أتعب و أقول شررريييح فضلا عن أخلاقه العالية\nالماده هذي عيبها انها تعتمد على الحفظ بشكل كبير ولكن اللي يركز مع دكتور عبيد راح يبدع ان شاء الله بالاختبارات ويطلع فاهم للمادة\nالعيب الوحيد في هذي المادة مع الدكتور هو اختباراته الطويله عباره عن 8 أسئلة مقالية و 45 سؤال اختياري تقريبا و بالنسبه لي كنت اشوف تصحيح الدكتور شديد جدا لكن في النهاية سوا Normal distribution و زود كل واحد 4 الى 5 درجات\nالقريد النهائي للدكتور B+\nقريدي عنده B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1461002-mkt250", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-obaid-al-shuridah/98464/9", "user": "HARD-WORKER", "ts": 1477387851000, "tid": 98464, "pn": 9}}]}', 1477387851000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_taki-mkt250', 'stk-abu_taki', 'MKT 250', 'doc', '{"docs": [{"id": "stk-dr-f98464", "n": "Dr. Obaid Al-Shuridah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MKT 250 -162\n\nالدكتور عبيد الشريدة … ملك الأخلاق والعلم … يحرجك بأخلاقه العالية واحترامه للطلاب ومراعاته لظروفهم\nشخصياً اشوفه افضل دكتور في كلية الإدارة الصناعية من ناحية الشرح الرائع والأخلاق العالية\n\nالتحضير : يومياً في بداية الكلاس … ويحضر المتأخرين نهاية الكلاس بدون ما يسجلهم تأخير ولا شي\nطريقة الشرح : شرح جبااار ويفهمك الكونسبت تماام … يستخدم سلايدات كمرجع ويضرب لك أمثلة من الواقع تسهل عليك الفهم… غالبا يخلص شابتر كل كلاس أو يخلص بحدود 80% منه ويكمل الكلاس التالي نظراً لطول الماتيريال ( 19 شابتر تقريبا )\nالكويزات : لا توجد\nالمياجر: طويلة ومقسمة بين MCQ ( من الـ TB ) و Written تقريبا بالتساوي … وفيه أسئلة إضافية في الملتبل شويس كبونص … يعني تقريبا يختبرك من 105 …\nماتيريال المياجر طويل شوي (6 او 7 شباتر) فالأفضل انك تذاكرها من قبل … قراءة الشابتر قبل الكلاس رح تسهل عليك المذاكرة لاحقا … الأسئلة المقالية تختبر فهمك للنقاط الرئيسية في الشابتر … خصوصا الأمور اللي فيها تعداد أو خطوات… عند الإجابة للسؤال تحتاج توضح مدى فهمك بشرح النقاط وذكر أمثلة … حاول تكتب اكبر قدر ممكن من المعلومات حتى تحصل على درجة طيبة\n\nالفاينل : نفس طريقة المياجر… لكنه كان اقصر هالسمستر ( 5 شباتر ) بسبب موضوع تقديم الإختبارات\n\nالقريد النهائي: قريدي في المادة B+ … قريد الدكتور A\nالصوت: واضح ولغة انجليزية ممتازة\n\nإضافات :\n- تجربة المادة مع الدكتور عبيد كانت ممتعة جداً … تستمتع في الكلاس وتحس نفسك فعلا طلعت بفايدة\n- أختلف مع اللي يقولون صعب جدا تطلع بقريد مع الدكتور عبيد … صحيح المادة معه يبيلها كرف في المياجر والفاينل لكنها مقدور عليها … وعموما الشغل بيكون فقط في هالاختبارات الثلاثة والبروجكت اللي رح تشتغل عليه مع مجموعتك… بحكم ان الدكتور ما يعطي كويزات او واجبات\n- الدكتور يعطي بونص درجتين اذا ما عندك ولا غياب … درجة ونصف اذا عندك غياب واحد … درجة اذا عندك غيابين… بالإضافة الى نقاط البونص في المياجر من خلال الأسئلة الاضافية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474674-mkt250", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-obaid-al-shuridah/98464/11", "user": "Abu_Taki", "ts": 1496799823000, "tid": 98464, "pn": 11}}]}', 1496799823000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9840-mkt250', 'stk-user9840', 'MKT 250', 'doc', '{"docs": [{"id": "stk-dr-f98464", "n": "Dr. Obaid Al-Shuridah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :بداية كل كلاس واشوي شديد .\nطريقة الشرح :\nيفتح السلايدات وياخذ الكونسبت ويبدا يشرح ويعطي امثلة من واقع الحياة في السعودية و كل الامثلة اللي يضربها في المملكة\nالدكتور خابز الكورس خباز لاتفوت عنه لاشاردة ولا واردة\nاستاذ كبير في التسويق\nلكن يعيبه قليلا ان الكلاسONE DIRECTION\nتقريبا يتكلم 75 دقيقة ماشاء الله بلا كلل ولا ملل , كم من المعلومات مهووووووووووووول ولكنه مفيد وراح تستفيد جدا معه\nلطلاب الماركتنق\nMKT 250 لاتنزله مع غيره .\n\nالمياجر: المنههههههههههههههههههههههههههههههههج طووووووووووووووووووووويل , تحتاج تذاكر اول باول كل ميجر عبارة عن 7 شباتر من النوع الطويل فأفضل شيء تبدا من بدري\n50% MCQ - 50% ESSAY\nالمقالي يجيب سؤالين الى ثلاثة\nعادي جدا يجيب لك جابتر كامل ويقول لك شرحه وكل نقطة تحتاج تكتب امثلة عليها\n-اطول كورس في حياتي الجامعية .\nاذا فاهم المتيريل وتقدر تكتب وتعبر كثير ماراح تشوفه صعب .\nمثلا كل سؤال 3 صفحات او اكثر .\nالفاينلات :نفس المياجر\nالقريد النهائي:A\nالصوت: جدا واضح واكسنت ممتاز\nإضافات :\nالامثلة اللي يقولها في الكلاس حاول تكتبها معه -بتستفيد منها كثيير وقت المذاكرة .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492584-mkt250", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-obaid-al-shuridah/98464/15", "user": "user9840", "ts": 1526556178000, "tid": 98464, "pn": 15}}]}', 1526556178000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-waleedx11-mkt250', 'stk-waleedx11', 'MKT 250', 'doc', '{"docs": [{"id": "stk-dr-f98464", "n": "Dr. Obaid Al-Shuridah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MKT250 - Term172\n\nالتحضير : أول ما يبدأ الكلاس وشديد شوي.\n\nطريقة الشرح : من السلايدات … شرحه ممتاز جدا ويربط المفاهيم بالحياة الواقعية ويطرح أمثلة عديدة على نفس الموضوع بحيث تترسخ المعلومة في الذهن … الدكتور عبيد ماشاء الله عليه متمكن من المادة بشكل رائع وعنده خبره لسنين طويلة فيها … يتقبل الأسئلة كذلك في وسط الشرح.\n\nالمياجر: قسمين قسم اختيارات وعددها 50 تقريبا وتكون أكثر من 50 اذا اضاف بونص و قسم ريتن شامل شامل بمعنى الكلمة … الاختبار طوووووويل ومرهق وأسئلة الريتن بالعادة تكون ثلاث اقسام : قسم اجباري حله و قسمين تختار منهم واحد بس … القسم الواحد عبارة عن ثلاث فقرات طووووويلة وشاملة للماتيريال … نصيحة لا تحل الثلاث اقسام كاملة لأن اذا سويتها بياخذ القسم الاجباري والقسم الأول فققققققط ويشطب عالثاني و حتى وان كنت مبدع في الثاني فلا تحل الاثنين وحل واحد بس … الدكتور تصحيحه شديد ولازم تكتب له كل شيء متعلق بالسؤال بالتفصيل الممل مع ذكر أمثلة ( يدك حتعورك يا صاحبي ) … لا تستغرب اذا نقصك على تعريف لأنك نسيت كلمة مهمة فحاول تكون حذر وانت تكتب له.\n\nالفاينلات :نفس المياجر\nالقريد النهائي للدكتور : A نظرا لشرحه الممتاز.\nالصوت: واضح وانجليزية ممتازة.\nإضافات :\nالمادة فيها بروجكت عليه 17% يتم تقديمه في أواخر الترم والدكتور شديد فيه شوي وما اتوقع أحد أخذ فيه فل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492711-mkt250", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-obaid-al-shuridah/98464/16", "user": "waleedx11", "ts": 1526694208000, "tid": 98464, "pn": 16}}]}', 1526694208000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-makkahboy-mkt250', 'stk-makkahboy', 'MKT 250', 'doc', '{"docs": [{"id": "stk-dr-f98464", "n": "Dr. Obaid Al-Shuridah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MKT250 - Term 181\n\nالتحضير: يحضر ببداية كل كلاس بالبطايق.\nكل طالب بأول أو ثاني كلاس يكتب اسمه على نوت كارد. وكل طالب عنده نوت كارد خاصة فيه. وينادي الأسماء بالبطايق هذي والغايب يسجل تاريخ الغياب في الكارد.\n\nطريقة الشرح: الدكتور عموما يشرح من السلايدات. والسلايدات ملياااااانة. وشرح الدكتور ماشاء الله ممتع وماتوصل للملل بعض الأحيان ويعطيك أمثلة ملموسة عشان تفهم. وماشاء الله عليه كفهم فاهم المادة ومتمكن منها.\n\nالكويزات: ماكان فيه كويزات\n\nالمياجر: كل ميجر عبارة عن التالي: (قسم long essay questions،وقسم short essays question، وقسم الmultiple choice)\nبالقسم الأول يجيك الظاهر سؤالين أو 3 تختار منهم واحد وتجاوبه بالكامل على كل فقراته\nالقسم الثاني أظن تجاوبه كلها.\nالقسم الثالث الاختيار المتعدد بناء على فهمك للمادة\nطبعا الwritten او القسمين الاولى ماهي ثابتة بالطريقة هذي وبالعدد هذا. يعني ممكن يجيب لك سؤالين ريتن ويقولك اختار واحد منهم ويكون شامل، ويجيب لك السؤال الثاني عبارة عن 3 أسئلة وتختار منهم اثنين وتجاوبهم كامل. وهكذا…\nبالمجمل الريتن طويل طويل ومرهق صراحة. لذلك لازم تكون حافظ وقارئ بشكل جيد. أنا كنت احفظ واقرأ من الكتاب وكانت جدا متعبة وتأخذ وقت.\n\nالفاينل: نفس نظام المياجر\n\nالصوت: واضح جدا ماشاء الله واللغة جيدة\n\nالقريد النهائي :\n\nإضافات: الدكتور كشرح يشرح مرة كويس ماشاء الله ويفهمك. لكن مما يعيبه أشعر انه يحب يصعب الأمور على الطلاب. مثلا البروجكت مايعطي أجد درجة كاملة.\nوالماتيريال النهائي مايخففه لو ايش ماصار كأنه قرآن منزل والماتيريال قائم على الفهم أكثر من الحفظ!. وفعليا اللي بينجحك الحفظ. مما يؤخذ على الدكتور أنه يوعد ويوعد ومايفي بوعوده سامحه الله. المياجر ما أعطانا ولا كلاس أوف والمفترض يعطينا! وعدنا وقالنا مثل دايما Don’t worry guys this is your right I will give you we will find classes before the end of the semester مو مشكلة وعدنا. جينا آخر أسبوع ووالله باقي لنا 3 شباتر ياجماعة والشابتر ثقيييل\nوما أعطانا شي. لا وأزيد، طلب منا نحضر كلاس إضافي مسائي آخر خميس عشان نقدم المشاريع.\n\nوأزيد: المياجر كلها ساعتين ونص، الفاينل اعطانا ساعتين بس!!.\n\nالدكتور كشر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504283-mkt250", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-obaid-al-shuridah/98464/17", "user": "makkahboy", "ts": 1546212798000, "tid": 98464, "pn": 17}}]}', 1546212798000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ksa-wolf-mkt250', 'stk-ksa-wolf', 'MKT 250', 'doc', '{"docs": [{"id": "stk-dr-f168064", "n": "Dr. Hussain Dhawi Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MKT 250 ---- Term 152\n\nالتحضير :\nيحضر كل كلاس في بدايته… ولكنه ليس شديد\nطريقة الشرح :\nشرح من السلايدات و قليلا من الكتاب\nتفهم معاه بس تطفش…\nالكويزات :\nكويز واحد و سهل… و أيضا حذف الشابتر اللي أعطانا عليه الكويز من ماتيريال الفاينال 😁2:\nالمياجر:\nاختيارات و أسئلة مقالية…\nالميجر الأول جاء تي بي\nالثاني ليس تي بي\nفانتبه مو كل مره يجي تي بي.\nالفاينلات :\nنفس المياجر… ليس تي بي\nالقريد النهائي:\nB+… إذا تبغى قريد بس A+\nالصوت:\nواضح\nإضافات :\n-- أعطانا بعد التجميع و عدم الغياب… كلها 5% بونص يعني قريد. الغياب عليه بونص 2% لو ما غبت. و أيضا عطانا بونص في الميجرين كلهم.\n-- الأسئلة المقالية شديد شوي في تصحيحهم فاكتب الأشياء المهمة كلها المطلوبة في السؤال. و فصل فيها لو كتب لك discuss.\n-- ذاكر التعاريف مهمة يجي منها كثير.\n-- الدكتور طيب جدا و متفاهم… و يجيب على الأسئلة. يحاول يساعد الطالب قدر ما يقدر الله يسعده. ❤️\n-- مثل ما قال عزوز… إذا تخصصك ليس ماركتنق أو ما تهتم للفهم ، لا تتردد أبدا في التنزيل معه. 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1452953-mkt250", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-al-qahtani-hussain-dhawi/168064/5", "user": "KSA-WOLF", "ts": 1467297374000, "tid": 168064, "pn": 5}}]}', 1467297374000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-practice-mkt250', 'stk-practice', 'MKT 250', 'doc', '{"docs": [{"id": "stk-dr-f168064", "n": "Dr. Hussain Dhawi Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MKT250 - TERM 152\n\n- الدكتور طيب واخلاقه كويسة\n- المياجر مو دايما TB فما تضمن - مجملا معقولة وكانت اختيارات وريتن ويدقق فيه لازم تشرح بشكل واضح\n- البروجكت بس كلام كانه ريبورت انقلش - فيه سامبل بالكتاب كان يقول لنا Follow the structure بمعناها\n- ما قصر ابدا بالدرجات - بونس بميجر ون وبونس بميجر تو وبونس للي ما غاب وبونس للي سوا الـSurvey تبع الديبارتمنت\n- شرحه قراية من السلايدات ويتكلم مع الطلاب - برضه اشوفه معقول بالشرح مهو التوب لكنه معقول\n- انصح فيه والله يكثر من امثاله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1456238-mkt250", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-al-qahtani-hussain-dhawi/168064/6", "user": "Practice", "ts": 1472627146000, "tid": 168064, "pn": 6}}]}', 1472627146000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
